def trend(seq):
    """Return True if sequence items broadly move in one direction.
    >>> trend([1, 2, 4, 20])
    True
    >>> trend([1, 20, 4, 10])
    False
    >>> trend([4, 1, 0, -10])
    True
    """
    if len(seq) < 2:
        return True

    increasing = None
    for i in range(1, len(seq)):
        if seq[i] > seq[i-1]:
            if increasing is False:
                return False
            increasing = True
        elif seq[i] < seq[i-1]:
            if increasing is True:
                return False
            increasing = False
        # if seq[i] == seq[i-1], no change to increasing direction

    return True

